(() => {
  const photoWidths={'lived-in-blonde':1800,'halli-studio':1365,'halli-portrait':1800,'blonde-transformation':1800,'natural-bronde':1800,'dimensional-blonde':1800,'dimensional-bronde':1800};
  function setPhoto(image,src,gallery=false){image.setAttribute('src',src);const match=/^assets\/([a-z-]+)\.jpg$/.exec(src);if(match&&photoWidths[match[1]]){image.srcset=`assets/${match[1]}-small.jpg 720w, ${src} ${photoWidths[match[1]]}w`;image.sizes=gallery?'(max-width: 760px) 44vw, 22vw':'(max-width: 760px) 88vw, 44vw';}else{image.removeAttribute('srcset');image.removeAttribute('sizes');}}
  const collections = {
    color:[{title:'Blonding & foil work',description:'From a soft brightness refresh to a bright, high-impact blonde.',price:'from $110'},{title:'Lived-in color & lowlights',description:'Customized dimension, blended roots, and a softer grow-out.',price:'from $100'},{title:'All-over color & root retouch',description:'Root maintenance, gray coverage, or customized all-over color.',price:'from $80'},{title:'Toner / gloss treatment',description:'Refresh your tone, refine your blonde, and add shine between appointments.',price:'from $45'}],
    extensions:[{title:'Extension consultation',description:'Let’s find the right length, volume, and shade for your look.',price:'Complimentary'},{title:'Extension installation',description:'Customized placement for added length, fullness, and a seamless blend.',price:'Custom quote'},{title:'Extension move-up',description:'Maintenance tailored to your natural hair growth.',price:'Custom quote'},{title:'Extension removal',description:'Professional removal with care for your natural hair.',price:'Custom quote'}],
    cuts:[{title:'Women’s haircut',description:'A personalized cut. Wash and style included.',price:'$40'},{title:'Dry trim',description:'A quick refresh to maintain your shape and hair health.',price:'$25'},{title:'Men’s haircut',description:'A cut tailored to your style. Straight razor neck shave add-on: $7.',price:'$30'},{title:'Children’s haircut',description:'For children 10 and under. Shampoo add-on: $5.',price:'$20'},{title:'Wash & style',description:'A relaxing shampoo, blow-dry, and heat styling or custom blowout.',price:'$30'},{title:'Special occasion styling',description:'Styling for events and celebrations. Quoted individually.',price:'from $50'}],
    gallery:[{src:'assets/blonde-transformation.jpg',alt:'Blonde hair transformation by Halli',caption:'Blonde transformation',url:'https://www.instagram.com/hairby.hallij/p/DfLQFC-lAbP/'},{src:'assets/natural-bronde.jpg',alt:'Natural bronde color with soft waves',caption:'Natural bronde',url:'https://www.instagram.com/hairby.hallij/p/DfDgM-GFKAF/'},{src:'assets/dimensional-blonde.jpg',alt:'Dimensional blonde with highlights and lowlights',caption:'Soft dimension',url:'https://www.instagram.com/hairby.hallij/p/De400BYFHyN/'},{src:'assets/dimensional-bronde.jpg',alt:'Dimensional bronde hair by Halli Miller',caption:'Dimensional bronde',url:'https://www.instagram.com/hairby.hallij/p/De0MSAWD1u1/'}],
    steps:[{title:'Find your inspiration',description:'Browse the portfolio and save the looks you love. Bring your ideas along.'},{title:'Let’s make a plan',description:'Not sure which service to choose? Message Halli about your hair and goals.'},{title:'Make yourself at home',description:'Book your visit at The Hair Studio Salon & Spa. Select Halli when choosing your stylist.'}],
    faqs:[{question:'How do I book an appointment?',answer:'Use the booking link to visit The Hair Studio Salon & Spa on Vagaro and select Halli as your stylist. You can also message @hairby.hallij on Instagram for help choosing a service.'},{question:'What if I’m not sure which color service I need?',answer:'Send Halli a message on Instagram with a photo of your current hair and your inspiration. She can help you decide where to start.'},{question:'How much will my color appointment cost?',answer:'Listed color prices are starting prices. The final price depends on your starting color, goals, hair length and density, and product needed. A personalized quote is discussed before your service begins.'},{question:'Can I book an extension consultation?',answer:'Yes! Extension consultations are free. Installation, move-ups, removal, and hair are quoted based on your needs. Message Halli to get started.'}]
  };
  const sectionNames = {home:'Home & navigation',hero:'Welcome',about:'About Halli',services:'Services & pricing',portfolio:'Portfolio',newClient:'New client guide',visit:'Social & salon details',faq:'Questions & answers',footer:'Footer'};
  const sections=[...document.querySelectorAll('main > section')].map(el=>{ const id=el.id||(el.classList.contains('new-client')?'newClient':el.classList.contains('faq')?'faq':'hero');el.dataset.section=id;return {id,label:sectionNames[id],el}; });
  function group(el){if(el.closest('header,.announcement'))return 'home';if(el.closest('footer'))return 'footer';return el.closest('[data-section]')?.dataset.section||'home';}
  const catalog=[];const bindings=new Map();let n=0;
  const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,{acceptNode(node){const el=node.parentElement;return node.data.trim()&&el?.closest('header,main,footer,.announcement')&&(!el.closest('[data-collection]')||el.closest('.pricing-note'))&&!el.closest('#year,.admin-entry,[data-phone],.round-note,.image-note,.script-note,script,style')&&!/^[↗↓↑⌖✧+\d\s]+$/.test(node.data.trim())?NodeFilter.FILTER_ACCEPT:NodeFilter.FILTER_REJECT;}});
  while(walker.nextNode()){const node=walker.currentNode;const id=`text-${n++}`;catalog.push({id,kind:'text',group:group(node.parentElement),label:node.data.trim().slice(0,65),value:node.data.trim(),long:node.data.trim().length>95});bindings.set(id,{node,initial:node.data});}
  document.querySelectorAll('header a,main a,footer a').forEach((el,i)=>{if(el.closest('[data-collection]')||el.classList.contains('admin-entry')||el.hasAttribute('data-phone')||el.closest('.round-note'))return;const id=`link-${i}`;catalog.push({id,kind:'url',group:group(el),label:el.textContent.trim(),value:el.getAttribute('href')});bindings.set(id,{el,attr:'href',initial:el.getAttribute('href')});});
  document.querySelectorAll('main img:not([data-collection] img)').forEach((el,i)=>{const id=`image-${i}`;catalog.push({id,kind:'image',group:group(el),label:el.alt,value:el.getAttribute('src'),alt:el.alt});bindings.set(id,{el,attr:'src',initial:el.getAttribute('src'),alt:el.alt});});
  catalog.push({id:'contact-phone',kind:'text',group:'visit',label:'Phone number (updates every call button)',value:'425-395-5021'});
  catalog.push({id:'page-title',kind:'text',group:'home',label:'Browser tab title',value:document.title},{id:'page-description',kind:'text',group:'home',label:'Search engine description',value:document.querySelector('meta[name=description]').content,long:true});
  const safeUrl=(url,image=false)=>typeof url==='string'&&(image?/^(?:assets\/|\/uploads\/|https?:\/\/)/i:/^(?:https?:\/\/|#|\/|mailto:|tel:)/i).test(url)?url:(image?'':'#');
  function el(tag,text,className){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(className)e.className=className;return e;}
  function renderCollections(config){
    for(const [key,defaults] of Object.entries(collections)){const items=config.collections?.[key]??defaults;const target=document.querySelector(`[data-collection="${key}"]`);const note=target.querySelector('.pricing-note');target.replaceChildren();
      items.forEach((item,index)=>{if(['color','cuts','extensions'].includes(key)){const row=el('div',undefined,'service-row');const copy=el('div');copy.append(el('h3',item.title),el('p',item.description));row.append(copy,el('span',item.price));target.append(row);}
      if(key==='gallery'){const button=el('button',undefined,'gallery-item');button.dataset.caption=item.caption;button.dataset.url=safeUrl(item.url);const image=el('img');setPhoto(image,safeUrl(item.src,true),true);image.alt=item.alt||item.caption;image.loading='lazy';image.style.objectFit=item.fit||'cover';image.style.objectPosition=item.position||'center';const caption=el('span',item.caption);caption.append(el('i','↗'));button.append(image,caption);target.append(button);}
      if(key==='steps'){const step=el('div');step.append(el('span',String(index+1).padStart(2,'0')),el('h3',item.title),el('p',item.description));target.append(step);}
      if(key==='faqs'){const detail=el('details');const summary=el('summary',item.question);summary.append(el('span','+'));detail.append(summary,el('p',item.answer));target.append(detail);}
      });if(note)target.append(note);
    }
  }
  const originalStyles=new WeakMap();
  function apply(config){const fields=config.fields||{};for(const [id,b] of bindings){const value=fields[id]??b.initial;if(b.node)b.node.data=value;else{if(b.attr==='src')setPhoto(b.el,safeUrl(value,true));else b.el.setAttribute(b.attr,safeUrl(value));if(b.attr==='src'){b.el.alt=fields[`${id}-alt`]??b.alt;b.el.style.objectFit=fields[`${id}-fit`]||'';b.el.style.objectPosition=fields[`${id}-position`]||'';}}}
    const phone=fields['contact-phone']??'425-395-5021';document.querySelectorAll('[data-phone]').forEach(a=>{const digits=phone.replace(/[^+0-9]/g,'');a.href='tel:'+(/^\d{10}$/.test(digits)?'+1'+digits:digits);const label=a.querySelector('.phone-number');if(label)label.textContent=phone;});
    document.title=fields['page-title']??catalog.find(x=>x.id==='page-title').value;document.querySelector('meta[name=description]').content=fields['page-description']??catalog.find(x=>x.id==='page-description').value;
    const theme=config.theme||{};for(const [key,property]of Object.entries({paper:'--paper',cream:'--cream',ink:'--ink',muted:'--muted',line:'--line',headingFont:'--serif',bodyFont:'--sans'})){if(theme[key])document.documentElement.style.setProperty(property,theme[key]);else document.documentElement.style.removeProperty(property);}
    renderCollections(config);
    const main=document.querySelector('main');const order=[...new Set([...(config.order||[]),...sections.map(s=>s.id)])];const ordered=order.map(id=>sections.find(s=>s.id===id)).filter(Boolean);ordered.forEach(s=>s.el.hidden=Boolean(config.hidden?.[s.id]));if([...main.children].map(s=>s.dataset.section).join(',')!==ordered.map(s=>s.id).join(','))main.append(...ordered.map(s=>s.el));
    document.querySelectorAll('h1,h2,h3,p,a,button,small,summary,.eyebrow,.hero-bottom,.hero-location,.service-row>span,.copyright').forEach(element=>{if(!originalStyles.has(element))originalStyles.set(element,parseFloat(getComputedStyle(element).fontSize));if(theme.textScale)element.style.fontSize=`${originalStyles.get(element)*Number(theme.textScale)}px`;else element.style.removeProperty('font-size');});
  }
  let config={};const editor=new URLSearchParams(location.search).get('editor')==='1'&&window.parent!==window;
  window.addEventListener('message',event=>{if(editor&&event.origin===location.origin&&event.source===parent&&event.data?.type==='halli:preview')apply(event.data.config);if(editor&&event.origin===location.origin&&event.source===parent&&event.data?.type==='halli:focus'){const section=sections.find(s=>s.id===event.data.section);if(section)section.el.scrollIntoView({behavior:'instant',block:'start'});else window.scrollTo({top:0,behavior:'instant'});}});
  fetch('/api/content').then(r=>{if(!r.ok)throw Error('Unable to load content');return r.json();}).then(data=>{config=data;apply(config);if(editor)parent.postMessage({type:'halli:ready',catalog,collections,sections:sections.map(({id,label})=>({id,label})),sectionNames,config},location.origin);}).catch(error=>{console.error(error);if(editor)parent.postMessage({type:'halli:error',message:'The website content could not be loaded. Please reload.'},location.origin);});
})();
